PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?o * ?p / 100) AS ?volumen) WHERE {
  { SELECT ?c (SUM(?oil) AS ?o) WHERE { ?wp a :WellProduction ; :concession ?c ; :oil ?oil } GROUP BY ?c }
  ?s a :Stake ; :concession ?c ; :partner ?co ; :percent ?p .
  { SELECT DISTINCT ?co WHERE { ?co a :Company ; :name ?n FILTER(STRSTARTS(UCASE(STR(?n)), "YPF")) } }
}
